sys.setrecursionlimit(2000)

def main():
    # Read all lines from standard input
    # Using sys.stdin.read().split() handles multiline inputs and varying whitespace gracefully
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
        D = int(next(iterator))

        grid = []
        for _ in range(H):
            grid.append(next(iterator))

    except StopIteration:
        return

    # Collect coordinates of all floor cells ('.')
    floor_coords = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                floor_coords.append((r, c))

    n = len(floor_coords)

    # Precompute reachable cells for each potential humidifier location
    # Since H, W <= 10, the grid is small (max 100 cells).
    # We can simply iterate over the grid for each candidate.
    reachable_sets = []

    for r, c in floor_coords:
        s = set()
        for rr in range(H):
            for cc in range(W):
                if abs(r - rr) + abs(c - cc) <= D:
                    s.add((rr, cc))
        reachable_sets.append(s)

    max_count = 0

    # Iterate over all unique pairs of floor cells
    # Number of floor cells is at most 10*10 = 100.
    # Pairs = 100*99/2 = 4950.
    # For each pair, union two sets of size at most 100. Very fast.

    for i in range(n):
        for j in range(i + 1, n):
            # Get the sets of reachable cells for the two chosen positions
            set_i = reachable_sets[i]
            set_j = reachable_sets[j]

            # Union the sets
            combined = set_i | set_j

            # Count how many of these are actually floor cells
            count = 0
            for cell_r, cell_c in combined:
                if grid[cell_r][cell_c] == '.':
                    count += 1

            if count > max_count:
                max_count = count

    print(max_count)

