import sys

def main():
    # Read input from stdin
    input_str = sys.stdin.read().strip()
    if not input_str:
        return

    # Parse the four integers A, B, C, D
    try:
        parts = list(map(int, input_str.split()))
    except ValueError:
        return

    if len(parts) != 4:
        return

    A, B, C, D = parts[0], parts[1], parts[2], parts[3]

    # Iterate through all possible cards that could be added (1 to 13)
    # A Full House is formed by having 3 cards of one rank and 2 of another.
    can_form = False
    for x in range(1, 14):
        # Combine the original 4 cards with the potential new card x
        cards = [A, B, C, D, x]

        # Count the frequency of each card value
        freq = {}
        for c in cards:
            freq[c] = freq.get(c, 0) + 1

        # Check if the frequencies match the Full House criteria {3, 2}
        if sorted(freq.values()) == [2, 3]:
            can_form = True
            break

    if can_form:
        print("Yes")
    else:
        print("No")

