    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Identify all indices where a strictly increasing subarray of length k starts
        start_indices = []

        for i in range(n - k + 1):
            is_increasing = True
            for j in range(k - 1):
                if nums[i + j + 1] <= nums[i + j]:
                    is_increasing = False
                    break
            if is_increasing:
                start_indices.append(i)

        # Check if there are two adjacent subarrays (indices a and b = a + k) both in start_indices
        for i in range(len(start_indices)):
            if start_indices[i] + k < len(start_indices) and start_indices[i + 1] == start_indices[i] + k:
                return True

        return False

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)

        # Check if a subarray of length k starting at index i is strictly increasing
        def is_increasing(i):
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    return False
            return True

        # We need to find two adjacent subarrays that are both strictly increasing.
        # Adjacent means the second starts exactly k positions after the first.
        # So we check every possible starting position i from 0 to n - 2*k.
        # If both subarray[i..i+k-1] and subarray[i+k..i+2k-1] are strictly increasing, return True.

        for i in range(n - k + 1):
            if is_increasing(i) and is_increasing(i + k):
                return True

        return False

