class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = []

        for i in range(n):
            if nums[i] == 0:
                result.append(nums[i])
            elif nums[i] > 0:
                # Move nums[i] steps to the right
                target_index = (i + nums[i]) % n
                result.append(target_index)
            else:
                # Move abs(nums[i]) steps to the left
                steps_left = -nums[i]
                target_index = (i - steps_left) % n
                result.append(target_index)

        return result

