    def maxRectangleArea(self, points: List[List[int]]) -> int:
        n = len(points)
        if n < 4:
            return -1

        # Use a set for fast lookup
        point_set = set()
        for p in points:
            point_set.add(tuple(p))

        max_area = -1

        # Group points by y-coordinate
        y_groups = {}
        for p in points:
            y, x = p[1], p[0]
            if y not in y_groups:
                y_groups[y] = []
            y_groups[y].append(x)

        # Sort x-coordinates in each group
        for y in y_groups:
            y_groups[y].sort()

        # Sorted list of unique y-coordinates
        sorted_ys = sorted(y_groups.keys())

        # Iterate over all pairs of rows
        for i in range(len(sorted_ys)):
            for j in range(i + 1, len(sorted_ys)):
                y1 = sorted_ys[i]
                y2 = sorted_ys[j]

                # Get set of x-coordinates for both rows
                xs1 = set(y_groups[y1])
                xs2 = set(y_groups[y2])

                # Find common x-coordinates
                common_xs = xs1.intersection(xs2)

                if len(common_xs) < 2:
                    continue

                # Sort common x-coordinates
                common_xs_list = sorted(list(common_xs))

                # Check each adjacent pair of x-coordinates
                for k in range(len(common_xs_list) - 1):
                    x_left = common_xs_list[k]
                    x_right = common_xs_list[k+1]

                    # Calculate area
                    area = (x_right - x_left) * (y2 - y1)

                    # Define the four corners
                    corners = {
                        (x_left, y1),
                        (x_right, y1),
                        (x_left, y2),
                        (x_right, y2)
                    }

                    # Check if any other point lies inside or on the border
                    valid = True
                    for p in points:
                        px, py = p[0], p[1]
                        if x_left <= px <= x_right and y1 <= py <= y2:
                            if px == x_left and py == y1:
                                continue
                            if px == x_right and py == y1:
                                continue
                            if px == x_left and py == y2:
                                continue
                            if px == x_right and py == y2:
                                continue
                            # This point is either on the edge (non-corner) or inside
                            valid = False
                            break

                    if valid:
                        max_area = max(max_area, area)

        return max_area

