class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # dp[r][c] will store a dictionary where key is the XOR value of paths from (0,0) to (r,c)
        # and value is the count of such paths.
        # Initialize with the starting cell
        dp = [[{} for _ in range(n)] for _ in range(m)]

        # Base case: starting at (0,0)
        start_val = grid[0][0]
        dp[0][0][start_val] = 1

        # Iterate through each cell
        for r in range(m):
            for c in range(n):
                if r == 0 and c == 0:
                    continue

                current_xors = dp[r][c]

                # Check possible previous cells: (r-1, c) [from top] and (r, c-1) [from left]
                prev_cells = []
                if r > 0:
                    prev_cells.append((r - 1, c))
                if c > 0:
                    prev_cells.append((r, c - 1))

                for pr, pc in prev_cells:
                    if pr < 0 or pc < 0:
                        continue

                    # Iterate over all possible XOR values from the previous cell
                    for prev_xor, count in dp[pr][pc].items():
                        new_xor = prev_xor ^ grid[r][c]

                        # Update current cell's dp table
                        if new_xor not in current_xors:
                            current_xors[new_xor] = 0
                        current_xors[new_xor] += count

                        if current_xors[new_xor] >= MOD:
                            current_xors[new_xor] -= MOD

                dp[r][c] = current_xors

        # The result is the number of paths ending at (m-1, n-1) with XOR equal to k
        return dp[m-1][n-1].get(k, 0)

