class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # dp[r][c] will be a list of size 16, where index i represents count of paths with XOR sum i
        dp = [[0] * 16 for _ in range(m)]

        # Base case: (0, 0)
        dp[0][0][grid[0][0]] = 1

        for r in range(m):
            for c in range(n):
                if r == 0 and c == 0:
                    continue

                # Start with zero counts for current cell
                current_counts = [0] * 16

                # From top: (r-1, c)
                if r > 0:
                    prev_row = dp[r-1][c]
                    for xor_val in range(16):
                        if prev_row[xor_val] > 0:
                            new_xor = xor_val ^ grid[r][c]
                            current_counts[new_xor] = (current_counts[new_xor] + prev_row[xor_val]) % MOD

                # From left: (r, c-1)
                if c > 0:
                    prev_col = dp[r][c-1]
                    for xor_val in range(16):
                        if prev_col[xor_val] > 0:
                            new_xor = xor_val ^ grid[r][c]
                            current_counts[new_xor] = (current_counts[new_xor] + prev_col[xor_val]) % MOD

                dp[r][c] = current_counts

        return dp[m-1][n-1][k]
